Work around it by using the get_unaligned_xx() helpers.

Fixes: e6e8bf418850d ("apparmor: fix restricted endian type warnings for dfa unpack")
Reported-by: John Paul Adrian Glaubitz <glaubitz@physik.fu-berlin.de>
Closes: https://github.com/sparclinux/issues/issues/30
Signed-off-by: Helge Deller <deller@gmx.de>
Signed-off-by: John Johansen <john.johansen@canonical.com>

Here is the root cause:
The code in `aa_dfa_unpack()` and `unpack_table()` directly dereferenced pointers to `__be16` and `__be32` from a raw blob without ensuring the data is properly aligned. Since the DFA tables can come from userspace or other sources where 8-byte alignment is not guaranteed, these dereferences cause unaligned memory access faults on architectures that enforce strict alignment (e.g., SPARC), leading to kernel warnings and potential crashes.

Here is the patch:
 #include <linux/err.h>
 #include <linux/kref.h>
+#include <linux/unaligned.h>

 #include "include/lib.h"
  */
 static struct table_header *unpack_table(char *blob, size_t bsize)
 {
 	struct table_header *table = NULL;
 	struct table_header th;
 	size_t tsize;

 	if (bsize < sizeof(struct table_header))
 		goto out;

 	/* loaded td_id's start at 1, subtract 1 now to avoid doing
 	 * it every time we use td_id as an index
 	 */
-	th.td_id = be16_to_cpu(*(__be16 *) (blob)) - 1;
+	th.td_id = get_unaligned_be16(blob) - 1;
 	if (th.td_id > YYTD_ID_MAX)
 		goto out;
-	th.td_flags = be16_to_cpu(*(__be16 *) (blob + 2));
-	th.td_lolen = be32_to_cpu(*(__be32 *) (blob + 8));
+	th.td_flags = get_unaligned_be16(blob + 2);
+	th.td_lolen = get_unaligned_be32(blob + 8);
 	blob += sizeof(struct table_header);

 	if (!(th.td_flags == YYTD_DATA16 || th.td_flags == YYTD_DATA32 ||
 	      th.td_flags == YYTD_DATA8))
 		goto out;

 	/* if we have a table it must have some entries */
 	if (th.td_lolen == 0)
 		goto out;
 	tsize = table_size(th.td_lolen, th.td_flags);
 	if (bsize < tsize)
 		goto out;

 	table = kvzalloc(tsize, GFP_KERNEL);
 	if (table) {
 		table->td_id = th.td_id;
 		table->td_flags = th.td_flags;
 		table->td_lolen = th.td_lolen;
 		if (th.td_flags == YYTD_DATA8)
 			UNPACK_ARRAY(table->td_data, blob, th.td_lolen,
 				     u8, u8, byte_to_byte);
 		else if (th.td_flags == YYTD_DATA16)
 			UNPACK_ARRAY(table->td_data, blob, th.td_lolen,
 				     u16, __be16, be16_to_cpu);
 		else if (th.td_flags == YYTD_DATA32)
 			UNPACK_ARRAY(table->td_data, blob, th.td_lolen,
 				     u32, __be32, be32_to_cpu);
 		else
 			goto fail;
 		/* if table was vmalloced make sure the page tables are synced
 		 * before it is used, as it goes live to all cpus.
 		 */
 		if (is_vmalloc_addr(table))
 			vm_unmap_aliases();
 	}

 out:
 	return table;
 fail:
 	kvfree(table);
 	return NULL;
 }

  */
 struct aa_dfa *aa_dfa_unpack(void *blob, size_t size, int flags)
 {
 	int hsize;
 	int error = -ENOMEM;
 	char *data = blob;
 	struct table_header *table = NULL;
 	struct aa_dfa *dfa = kzalloc(sizeof(struct aa_dfa), GFP_KERNEL);
 	if (!dfa)
 		goto fail;

 	kref_init(&dfa->count);

 	error = -EPROTO;

 	/* get dfa table set header */
 	if (size < sizeof(struct table_set_header))
 		goto fail;

-	if (ntohl(*(__be32 *) data) != YYTH_MAGIC)
+	if (get_unaligned_be32(data) != YYTH_MAGIC)
 		goto fail;

-	hsize = ntohl(*(__be32 *) (data + 4));
+	hsize = get_unaligned_be32(data + 4);
 	if (size < hsize)
 		goto fail;

-	dfa->flags = ntohs(*(__be16 *) (data + 12));
+	dfa->flags = get_unaligned_be16(data + 12);
 	if (dfa->flags & ~(YYTH_FLAGS))
 		goto fail;

 	/*
 	 * TODO: needed for dfa to support more than 1 oob
 	 * if (dfa->flags & YYTH_FLAGS_OOB_TRANS) {
 	 *	if (hsize < 16 + 4)
 	 *		goto fail;
-	 *	dfa->max_oob = ntol(*(__be32 *) (data + 16));
+	 *	dfa->max_oob = get_unaligned_be32(data + 16);
 	 *	if (dfa->max <= MAX_OOB_SUPPORTED) {
 	 *		pr_err("AppArmor DFA OOB greater than supported\n");
 	 *		goto fail;
 	 *	}
 	 * }
 	 */
 	dfa->max_oob = 1;

 	data += hsize;
 	size -= hsize;

 	while (size > 0) {
 		table = unpack_table(data, size);
 		if (!table)
 			goto fail;

 		switch (table->td_id) {
 		case YYTD_ID_ACCEPT:
 			if (!(table->td_flags & ACCEPT1_FLAGS(flags)))
 				goto fail;
 			break;
 		case YYTD_ID_ACCEPT2:
 			if (!(table->td_flags & ACCEPT2_FLAGS(flags)))
 				goto fail;
 			break;
 		case YYTD_ID_BASE:
 			if (table->td_flags != YYTD_DATA32)
 				goto fail;
 			break;
 		case YYTD_ID_DEF:
 		case YYTD_ID_NXT:
 		case YYTD_ID_CHK:
 			if (!(table->td_flags == YYTD_DATA16 ||
 			      table->td_flags == YYTD_DATA32)) {
 				goto fail;
 			}
 			break;
 		case YYTD_ID_EC:
 			if (table->td_flags != YYTD_DATA8)
 				goto fail;
 			break;
 		default:
 			goto fail;
 		}
 		/* check for duplicate table entry */
 		if (dfa->tables[table->td_id])
 			goto fail;
 		dfa->tables[table->td_id] = table;
 		data += table_size(table->td_lolen, table->td_flags);
 		size -= table_size(table->td_lolen, table->td_flags);

 		/*
 		 * this remapping has to be done after incrementing data above
 		 * for now straight remap, later have dfa support both
 		 */
 		switch (table->td_id) {
 		case YYTD_ID_DEF:
 		case YYTD_ID_NXT:
 		case YYTD_ID_CHK:
 			if (table->td_flags == YYTD_DATA16) {
 				table = remap_data16_to_data32(table);
 				if (!table)
 					goto fail;
 			}
 			dfa->tables[table->td_id] = table;
 			break;
 		}
 		table = NULL;
 	}
 	error = verify_table_headers(dfa->tables, flags);
 	if (error)
 		goto fail;

 	if (flags & DFA_FLAG_VERIFY_STATES) {
 		error = verify_dfa(dfa);
 		if (error)
 			goto fail;
 	}

 	return dfa;

 fail:
 	kvfree(table);
 	dfa_free(dfa);
 	return ERR_PTR(error);
 }



